#!/bin/bash

set -xe

# setup
android_project_dir_path="$CANGJIE_TEST/testsuites/HLT/configs/cjnative/android/MyApplication"
# temp working dir for current test case generated by cangjie test framework.
test_case_dir_path=$PWD
p="$android_project_dir_path/app/src/main/java/UNNAMED"
rm -rf $p
# copy output java mirror generated by cjc to android project.
cp "$test_case_dir_path"/java-gen/* "$p"
cp "$CANGJIE_TEST/testsuites/HLT/compiler/cjnative/FFI/jffi/android/util/logger.cj" "$test_case_dir_path/logger.cj"

android_java_dir_path="$android_project_dir_path/app/src/main/java"
hello_dir_path="$android_java_dir_path/com/example/myapplication"
rm -rf "$hello_dir_path"
mkdir -p "$hello_dir_path"
cp "$CANGJIE_TEST/testsuites/HLT/compiler/cjnative/FFI/jffi/android/util/Logger.java" "$test_case_dir_path/Logger.java"

cp "$test_case_dir_path/Logger.java" "$hello_dir_path/Logger.java"

# run
android_project_dir_path="$CANGJIE_TEST/testsuites/HLT/configs/cjnative/android/MyApplication"


test_entry="MainInstrumentedTest.java"
main_entry="$1"
java_source_root="com"
cangjie_source_root="$3"

java_source_root_dir_name="$java_source_root"

# dir containing test case's java source files.
java_source_root_dir_path="$test_case_dir_path/$java_source_root_dir_name"

# dir containing java source files.
android_java_dir_path="$android_project_dir_path/app/src/main/java"
target="$android_java_dir_path/$java_source_root_dir_name"
# clear all .java & .class files.
rm -rf "$target"/*.java
rm -rf "$target"/*.class

# copying test case java source files to android studio project.
if [ -e "$java_source_root_dir_path" ]; then
	cp -rf "$java_source_root_dir_path" "$target"
	# compile java source files using javac.
	cd "$java_source_root_dir_path"
	javac "$java_source_root_dir_path/*.java"
	cd -
fi

# first, clear jniLibs.
jni_libs_dir_path="$android_project_dir_path/app/src/main/jniLibs/arm64-v8a"
rm -rf "$jni_libs_dir_path"
mkdir -p "$jni_libs_dir_path"

# copying Cangjie dynamic library to jniLibs.
cangjie_dylib_file_path="$test_case_dir_path/libUNNAMED.so"
cp "$cangjie_dylib_file_path" "$jni_libs_dir_path/libUNNAMED.so"
# copying necessary dynamic libraries from Cangjie SDK.
cangjie_runtime_lib_dir_path="$CANGJIE_HOME/runtime/lib/linux_android_aarch64_cjnative"
cp "$cangjie_runtime_lib_dir_path/*" "$jni_libs_dir_path"

# copying libc++_shared.so from Android NDK.
ndk_dir_path="$OHOS_ROOT/llvm/prebuilt/darwin-x86_64/sysroot/usr/lib/aarch64-linux-android/libc++_shared.so"
cp "$ndk_dir_path" "$jni_libs_dir_path/libc++_shared.so"

# copying instrumented test source file.
test_entry_file_path="$test_entry"
instrumented_test_dir_path="$android_project_dir_path/app/src/androidTest/java/com/example/myapplication"
cp "$test_entry_file_path" "$instrumented_test_dir_path/$test_entry"

# copying library-loader.jar to app/libs.
# this path is configured in app/build.gradle.kts
libs_dir_path="$android_project_dir_path/app/libs"
rm -rf "$libs_dir_path"
mkdir -p "$libs_dir_path"
cp "$CANGJIE_HOME/lib/library-loader.jar" "$libs_dir_path/library-loader.jar"

# run test case

cd "$android_project_dir_path"
./gradlew assembleDebug
./gradlew assembleAndroidTest

if [ -z "${DEVICE_ID}" ]; then
	DEVICE_ID="emulator-5554"
fi

apk_file_path="$android_project_dir_path/app/build/outputs/apk/debug/app-debug.apk"
adb -s "${DEVICE_ID}" install -r "${apk_file_path}"

# installing test apk
android_test_apk_file_path="$android_project_dir_path/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk"

adb -s "${DEVICE_ID}" install -r "${android_test_apk_file_path}"

# run tests
adb -s "$DEVICE_ID" shell am instrument -w -e junitXml "/sdcard/report.xml" "com.example.myapplication.test/androidx.test.runner.AndroidJUnitRunner"

# do cleaning
rm -rf "$android_project_dir_path/app/build"
rm -rf "$android_project_dir_path/app/libs"
rm -rf "$android_project_dir_path/app/src/main/jniLibs"
